window.OVA_CONTENT={"slug":"seccion-06-microbiologia-aplicada-y-bioseguridad","title":"Microbiología aplicada y bioseguridad","minutes":45,"summary":"Diferencia microorganismos benéficos, alterantes y patógenos y controla sus condiciones en procesos agroindustriales.","objective":"Analizar aplicaciones microbianas, bioinsumos, riesgos y trazabilidad.","stages":[{"eyebrow":"Diversidad","title":"1. Bacterias, hongos y levaduras","reading":"Las bacterias son procariotas. Los hongos son eucariotas y pueden ser unicelulares o multicelulares; las levaduras son hongos unicelulares con importancia fermentativa.","application":"La clasificación orienta preguntas sobre estructura y metabolismo, pero la función depende de especie, cepa y contexto.","activity":{"type":"match","question":"Relaciona grupo y característica.","pairs":[{"label":"Bacterias","value":"procariotas","option":"Procariotas"},{"label":"Hongos","value":"eucariotas","option":"Eucariotas"},{"label":"Levaduras","value":"unicelulares","option":"Hongos unicelulares"}],"answer":["procariotas","eucariotas","unicelulares"],"success":"La estructura básica ayuda a diferenciar grupos."}},{"eyebrow":"Crecimiento","title":"2. Condiciones que cambian la actividad","reading":"Temperatura, pH, disponibilidad de agua, oxígeno, nutrientes y tiempo determinan si una población crece o permanece limitada. Controlar estas variables es parte del diseño del proceso.","application":"El mismo microorganismo puede ser útil en un fermentador y causar alteración si aparece fuera del sistema controlado.","activity":{"type":"multi","question":"Selecciona condiciones de crecimiento.","options":["Temperatura","pH","Actividad de agua","Color de la etiqueta"],"answer":[0,1,2],"success":"El ambiente determina la actividad microbiana."}},{"eyebrow":"Función","title":"3. Beneficio, alteración o peligro","reading":"Muchos microorganismos fermentan, reciclan nutrientes o controlan otros organismos. Otros alteran productos o causan enfermedad. La función debe establecerse con identificación, evidencia y contexto.","application":"La presencia microbiana no equivale automáticamente a contaminación peligrosa.","activity":{"type":"choice","question":"¿Cuál afirmación es correcta?","options":["La función depende del organismo y del contexto","Todos los microorganismos son patógenos","Toda fermentación ocurre sin control"],"answer":[0],"success":"La microbiología aplicada distingue funciones y riesgos."}},{"eyebrow":"Fermentación","title":"4. Un proceso que debe controlarse","reading":"En una fermentación, cultivo, sustrato, temperatura, tiempo y condiciones sanitarias influyen en acidez, aroma, textura y estabilidad. La repetibilidad depende de estandarización y registros.","application":"Un cultivo iniciador sin trazabilidad puede explicar diferencias entre lotes.","activity":{"type":"order","question":"Ordena un control básico del proceso.","items":["Verificar cultivo y lote","Preparar sustrato y condiciones","Inocular","Monitorear tiempo, temperatura y pH","Registrar y evaluar producto"],"answer":[0,1,2,3,4],"success":"La calidad depende del control de todo el proceso."}},{"eyebrow":"Caso integrado","title":"5. Bioinsumos con evidencia","reading":"Biofertilizantes y biocontroladores pueden apoyar nutrición o manejo de plagas. Antes de adoptarlos deben revisarse identidad, registro aplicable, calidad, almacenamiento, eficacia y compatibilidad.","application":"Que un producto sea natural no elimina los riesgos ni la necesidad de seguimiento.","activity":{"type":"choice","question":"¿Qué propuesta es responsable?","options":["Prueba controlada con producto verificado y registros","Aplicación masiva sin evaluación","Uso de cualquier cultivo artesanal"],"answer":[0],"success":"Los bioinsumos requieren control y trazabilidad."}}],"number":"06","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};